# 函数 0 的前置文档注释
# 第二行说明
def func_0(alpha, beta=0, gamma="s0"):
    """函数 0 的文档字符串。

    Args:
        alpha (int): 第一个参数
        beta (int): 第二个参数，默认 0
        gamma (str): 第三个参数

    Returns:
        int: 计算结果
    """
    # 内部注释：准备数据
    data = [alpha, beta]  # 行尾注释
    total = 0
    for idx, value in enumerate(data):
        # 循环内注释
        total += value * idx
    return total  # 返回


class Klasse0:
    """类 0 的文档。"""

    # 方法 0 的文档
    def method_0(self, x):
        """方法文档。

        :param x: 输入值
        :type x: int
        :return: 输出值
        :rtype: int
        """
        # 方法内注释
        return x + 0


